<div class="col-12"><label class="form-label">التوقيع</label><canvas id="signature-pad" class="border rounded w-100" height="160"></canvas><input type="hidden" name="signature" id="signature"><button type="button" class="btn btn-sm btn-outline-secondary mt-2" id="clear">مسح التوقيع</button></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" required id="agree"><label class="form-check-label" for="agree">أقر بصحة البيانات أعلاه</label></div></div><div class="col-12"><button class="btn btn-primary">إرسال</button></div></form></div></div></main><script>const c=document.getElementById('signature-pad'),x=c.getContext('2d');let d=false;c.addEventListener('pointerdown',e=>{d=true;x.beginPath();x.moveTo(e.offsetX,e.offsetY)});c.addEventListener('pointermove',e=>{if(d){x.lineTo(e.offsetX,e.offsetY);x.stroke()}});window.addEventListener('pointerup',()=>d=false);document.getElementById('clear').onclick=()=>x.clearRect(0,0,c.width,c.height);document.getElementById('purchase-form').onsubmit=()=>document.getElementById('signature').value=c.toDataURL('image/png');</script></body></html>
